package com.example.HMS.service;

import com.example.HMS.dto.MedicalRecordDto;
import com.example.HMS.dto.MedicalRecordMapper;
import com.example.HMS.entity.Appointment;
import com.example.HMS.entity.Doctor;
import com.example.HMS.entity.MedicalRecord;
import com.example.HMS.entity.Patient;
import com.example.HMS.repository.AppointmentRepository;
import com.example.HMS.repository.DoctorRepository;
import com.example.HMS.repository.MedicalRecordRepository;
import com.example.HMS.repository.PatientRepository;
import com.example.HMS.repository.PrescriptionRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class MedicalRecordServiceTest {

    @Mock
    private PatientRepository patientRepository;

    @Mock
    private DoctorRepository doctorRepository;

    @Mock
    private MedicalRecordRepository medicalRepository;

    @Mock
    private PrescriptionRepository prescriptionRepository;

    @Mock
    private AppointmentRepository appointmentRepository;

    @InjectMocks
    private MedicalRecordService service;

    @Test
    // GreyTest trace: createMedicalRecord | IF-3-FALSE | BR-094 -> TP-064 -> TC-323
    void createMedicalRecord_withNullPrescriptionId_savesAndReturnsMappedRecord() {
        // Arrange
        Appointment appointment = new Appointment();
        appointment.setAppointmentId(2001L);

        Patient patient = new Patient();
        patient.setPatientId(4001L);
        appointment.setPatient(patient);

        Doctor doctor = new Doctor();
        doctor.setDoctorId(3001L);
        appointment.setDoctor(doctor);

        MedicalRecordDto request = new MedicalRecordDto();
        request.setDoctorId(3001L);
        request.setRecordId(null);
        request.setDiagnosis("Đau đầu");
        request.setPatientId(4001L);
        request.setTreatment("Nghỉ ngơi");
        request.setVisitDate(LocalDate.of(2025, 1, 15));
        request.setAppointmentId(2001L);
        request.setPrescriptionId(null);

        MedicalRecordMapper realMapper = new MedicalRecordMapper(appointmentRepository);
        service = new MedicalRecordService(
                patientRepository,
                doctorRepository,
                medicalRepository,
                prescriptionRepository,
                appointmentRepository,
                realMapper);

        when(appointmentRepository.findById(2001L)).thenReturn(Optional.of(appointment));
        when(medicalRepository.save(any(MedicalRecord.class)))
                .thenAnswer(invocation -> invocation.getArgument(0));

        // Act
        MedicalRecordDto result = service.createMedicalRecord(request);

        // Assert
        ArgumentCaptor<MedicalRecord> savedRecordCaptor = ArgumentCaptor.forClass(MedicalRecord.class);
        verify(medicalRepository).save(savedRecordCaptor.capture());
        MedicalRecord savedRecord = savedRecordCaptor.getValue();

        assertEquals("Đau đầu", savedRecord.getDiagnosis());
        assertEquals("Nghỉ ngơi", savedRecord.getTreatment());
        assertEquals(LocalDate.of(2025, 1, 15), savedRecord.getVisitDate());
        assertEquals(appointment, savedRecord.getAppointment());
        assertEquals(patient, savedRecord.getPatient());
        assertEquals(doctor, savedRecord.getDoctor());
        assertNull(savedRecord.getPrescription());

        assertEquals("Đau đầu", result.getDiagnosis());
        assertEquals("Nghỉ ngơi", result.getTreatment());
        assertEquals(LocalDate.of(2025, 1, 15), result.getVisitDate());
        assertEquals(2001L, result.getAppointmentId());
        assertEquals(4001L, result.getPatientId());
        assertEquals(3001L, result.getDoctorId());
        assertNull(result.getPrescriptionId());

        verify(prescriptionRepository, never()).findById(org.mockito.ArgumentMatchers.<Long>any());
    }
}
